/**
 * This app's i18n entry point: the shared runtime bound to this app's own mapping.
 *
 * Import `useTranslation` FROM HERE, not from `./kit`. The kit is generated by
 * `libs/ui-kit/sync.mjs` and overwritten on every sync.
 *
 * There is no English catalog. English is the source, written at the call site, and it doubles as
 * the lookup key - see catalogs/vi.ts.
 */
import { vi } from './catalogs/vi.ts'
import type { Catalogs, TranslateParams } from './kit/translate.ts'
import { EDITION_CATALOGS } from '@edition-i18n'

// The edition's own pages bring their own translations (src/edition/types.ts) - none on Desktop and
// the Home Server, the Enterprise pages' on Enterprise. They never repeat a key of this catalog;
// libs/ui-kit/i18n/check-catalogs.mjs fails one that does.
export const catalogs: Catalogs = { vi: { ...vi, ...EDITION_CATALOGS.vi } }

/**
 * The `t` a component gets from `useTranslation`, as a type a PLAIN FUNCTION can accept.
 *
 * Some prose is built outside React - `formatSessionReset` turns a quota into a sentence, and it
 * is called from three different components. A hook cannot be used there, and duplicating the
 * sentence into each caller is how two screens come to word the same fact differently. So those
 * helpers take `t` as their last argument and stay pure.
 *
 * Prefer a component and `useTranslation()` where there is a choice. This is for the cases where
 * there genuinely is not one.
 */
export type Translate = (source: string, params?: TranslateParams) => string

export {
  I18nProvider,
  useI18n,
  useTranslation,
  LOCALES,
  LOCALE_NAMES,
  DEFAULT_LOCALE,
  type Locale,
} from './kit/index.ts'
